package com.logatron.auth.persistence;
import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.Instant;import java.util.*;
public interface ProjectMembershipRepository extends JpaRepository<ProjectMembershipEntity,UUID>{@Query("select distinct m from ProjectMembershipEntity m join fetch m.project p join fetch p.company join fetch m.role join fetch m.user where m.user.id=:userId and m.validFrom<=:now and (m.validUntil is null or m.validUntil>:now)") List<ProjectMembershipEntity> findActiveDetailedForUser(@Param("userId")UUID userId,@Param("now")Instant now);@Query("select distinct m from ProjectMembershipEntity m join fetch m.project join fetch m.role join fetch m.user where m.project.id=:projectId") List<ProjectMembershipEntity> findDetailedByProjectId(@Param("projectId")UUID projectId);}
